<script setup lang="js" xmlns="">
import {ref} from "vue";
const { $mitt } = useNuxtApp();
const PlayList=ref([])
const currentHover=ref(-1)
const nowPlay=ref("")
onMounted(async()=>{

  const [example] = await Promise.all([document.querySelector(".drawer")]);
  const openButton = example.querySelector(".open");
  const closeButton = example.querySelector(".close");
  const navigationDrawer = example.querySelector("mdui-navigation-drawer")
  openButton.addEventListener("click", () => navigationDrawer.open = true);
  closeButton.addEventListener("click", () => navigationDrawer.open = false);
  await reFreshPlaylist()

  const topSang=PlayList.value[0];
  CurrentPlaySangsInfo.img=topSang.img
  CurrentPlaySangsInfo.url=topSang.url
  CurrentPlaySangsInfo.author=topSang.author
  CurrentPlaySangsInfo.album=topSang.album
  CurrentPlaySangsInfo.title=topSang.title
  $mitt.on('add',(data)=>{
    PlayList.value.push(data);
    if(PlayList.value[CurrentPlaySangsInfo.index].url===""){NextSang()}
  })
  $mitt.on('top',(data)=>{
    if(PlayList.value[CurrentPlaySangsInfo.index].url===""){PlayList.value.push(data);NextSang();return}
    if(CurrentPlaySangsInfo.index){
      const top=PlayList.value[CurrentPlaySangsInfo.index];
      PlayList.value.pop();
      PlayList.value.push(data);
      PlayList.value.push(top);
    }else{ PlayList.value.push(data)}
  })
  $mitt.on('rep',(data)=>{
    ReplaceSang(data);
  })
  $mitt.on('route',()=>{
    navigationDrawer.open = false;
  })

})
const reFreshPlaylist=async ()=>{
  const res = await GetPlayList({uid:"1"});
  PlayList.value=res.data.playlist;
  PlayList.value = PlayList.value.filter(item => item !== null && item !== undefined&&item.url);
  if(!PlayList.value[0]){PlayList.value.push(CurrentPlaySangsInfo)}
}
const ReplaceSang=(data)=>{
  PlayList.value[CurrentPlaySangsInfo.index]=data
  CurrentPlaySangsInfo.img=data.img
  CurrentPlaySangsInfo.url=data.url
  CurrentPlaySangsInfo.author=data.author
  CurrentPlaySangsInfo.album=data.album
  CurrentPlaySangsInfo.title=data.title
  CurrentPlaySangsInfo.isPause=false
  $mitt.emit('Play');

}
const CurrentPlaySangsInfo=reactive({
  index:0,
  img:"",
  url:"",
  album:"",
  author:"",
  title:"NULL",
  isPause:true
})

const deleteFormPlayList= async (index)=>{
  const sid=PlayList.value[index].id
  await DeletePlayList({uid:"1",sid:sid})
  PlayList.value= PlayList.value.filter(item => item.id!==sid);
}

const NextSang=()=>{
  if(CurrentPlaySangsInfo.index>=PlayList.value.length-1){
    ElMessage.error("It's last Sang")
    return;
  }
  CurrentPlaySangsInfo.index++;
  CurrentPlaySangsInfo.img=PlayList.value[CurrentPlaySangsInfo.index].img;
  CurrentPlaySangsInfo.url=PlayList.value[CurrentPlaySangsInfo.index].url;
  CurrentPlaySangsInfo.author=PlayList.value[CurrentPlaySangsInfo.index].author
  CurrentPlaySangsInfo.album=PlayList.value[CurrentPlaySangsInfo.index].album
  CurrentPlaySangsInfo.title=PlayList.value[CurrentPlaySangsInfo.index].title;
}
const PreSang=()=>{
  if(PlayList.value[CurrentPlaySangsInfo.index-1]===""||CurrentPlaySangsInfo.index===0){
    ElMessage.error("It's first Sang")
    return;
  }
  CurrentPlaySangsInfo.index--;
  ElMessage.success(CurrentPlaySangsInfo.index)
  CurrentPlaySangsInfo.img=PlayList.value[CurrentPlaySangsInfo.index].img;
  CurrentPlaySangsInfo.url=PlayList.value[CurrentPlaySangsInfo.index].url;
  CurrentPlaySangsInfo.author=PlayList.value[CurrentPlaySangsInfo.index].author
  CurrentPlaySangsInfo.album=PlayList.value[CurrentPlaySangsInfo.index].album
  CurrentPlaySangsInfo.title=PlayList.value[CurrentPlaySangsInfo.index].title;
}

</script>

<template>
<div class="w-screen h-screen flex flex-row  items-center justify-items-center">
  <keep-alive>
    <player
        :author="CurrentPlaySangsInfo.author"
        :url="CurrentPlaySangsInfo.url"
        :title="CurrentPlaySangsInfo.title"
        :img="CurrentPlaySangsInfo.img"
        :is-paused="CurrentPlaySangsInfo.isPause"
        :album="CurrentPlaySangsInfo.album"
        :next="NextSang"
        :pre="PreSang"
        :finished="NextSang"
        class="mt-28"
    ></player>
  </keep-alive>

  <div class="w-1/5 h-full absolute right-2">
    <div class="drawer">
        <mdui-navigation-drawer  class=" h-full " placement="right">
          <mdui-button class="close" variant="tonal">
